        from "MTG_PURCHASED_PORTFOLIO_STATUS_HIST"
        where "PORTFOLIO_ID" = @P203_PORTFOLIO_ID::bigint
        order by "CHANGE_AT" desc
        """;

    public const string P208_HEADER = """
