        select a."SELLER_CONTRACT_NO", u."UNIT_CODE", coalesce(a."CONTRACT_VALUE", 0) "CV", coalesce(a."PAID_VALUE", 0) "PV", coalesce(a."DEAL_DECISION_CODE", 'SELECTED') "DEC"
